const reports=[{id:'RPR-1042',category:'Streetlights',icon:'lightbulb',color:'amber',title:'Streetlight not working',area:'Near Shankar Nagar market',status:'In progress',group:'Active',time:'2 hours ago',department:'Electrical & Street Lighting Department',description:'A streetlight on the main market road is not working, leaving this stretch dark after sunset.'},{id:'RPR-1039',category:'Roads',icon:'route',color:'blue',title:'Pothole on the main road',area:'Civil Lines, near the post office',status:'Reported',group:'Active',time:'5 hours ago',department:'Road Maintenance Department',description:'A pothole near the post office is affecting people travelling along the road.'},{id:'RPR-1031',category:'Waste',icon:'trash-2',color:'green',title:'Garbage pile cleared',area:'Telibandha, near the lake entrance',status:'Resolved',group:'Resolved',time:'Yesterday',department:'Solid Waste Management Department',description:'The reported garbage has been cleared. The report is marked resolved in this sample.'},{id:'RPR-1018',category:'Water',icon:'droplets',color:'cyan',title:'Water leaking from roadside pipe',area:'Katora Talab, near the community hall',status:'Needs follow-up',group:'Follow-up',time:'3 days ago',department:'Water Supply Department',description:'Water continues to leak from a roadside pipe. This sample report is awaiting a follow-up.'}];
let status='All',category='',query='',city='Raipur';const $=s=>document.querySelector(s);const icons=()=>window.lucide?.createIcons();
function render(){let shown=city==='Raipur'?reports.filter(r=>(status==='All'||r.group===status)&&(!category||r.category===category)&&(`${r.title} ${r.area} ${r.id}`.toLowerCase().includes(query.toLowerCase()))):[];$('#reportList').innerHTML=shown.length?shown.map(r=>`<button class="report-row" data-report="${r.id}" aria-label="View ${r.title}"><span class="report-symbol ${r.color}"><i data-lucide="${r.icon}"></i></span><span class="report-body"><span class="report-title">${r.title}</span><span class="report-meta"><i data-lucide="map-pin"></i>${r.area}<span class="meta-dot time">·</span><span class="time">${r.time}</span></span></span><span class="row-end"><span class="badge ${r.group==='Resolved'?'resolved':r.group==='Follow-up'?'follow':'progress'}">${r.status}</span><i data-lucide="chevron-right"></i></span></button>`).join(''):`<div class="empty">${city!=='Raipur'?'Sample reports are currently available for Raipur.':'No matching reports. Try another category or search.'}</div>`;$('#categoryFilter').hidden=!category;$('#categoryFilter').innerHTML=category?`Showing ${category==='Roads'?'roads & potholes':category.toLowerCase()} reports <button id="clearCategory">Clear filter ×</button>`:'';document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category));icons();document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>detail(b.dataset.report));$('#clearCategory')?.addEventListener('click',()=>{category='';render()})}
const sheet=$('#sheet');function openSheet(html){$('#sheetContent').innerHTML=html;sheet.showModal();document.body.style.overflow='hidden';icons()}function closeSheet(){sheet.close();document.body.style.overflow=''}$('#closeSheet').onclick=closeSheet;sheet.addEventListener('click',e=>{if(e.target===sheet){let r=sheet.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet()}});sheet.addEventListener('close',()=>document.body.style.overflow='');
function detail(id){let r=reports.find(x=>x.id===id);openSheet(`<span class="category-icon ${r.color}"><i data-lucide="${r.icon}"></i></span><h2>${r.title}</h2><span class="badge ${r.group==='Resolved'?'resolved':r.group==='Follow-up'?'follow':'progress'}">${r.status}</span><p>${r.description}</p><div class="detail-label">LOCATION</div><div class="detail-value">${r.area}, Raipur</div><div class="detail-label">RESPONSIBLE DEPARTMENT</div><div class="detail-value">${r.department}</div><div class="detail-label">REPORT ID</div><div class="detail-value">${r.id}</div><p style="font-size:11px">Sample report for the home screen prototype. Department and status are illustrative.</p><button class="primary" id="done">Back to home</button>`);$('#done').onclick=closeSheet}
document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{status=b.dataset.status;document.querySelectorAll('[data-status]').forEach(t=>t.setAttribute('aria-selected',String(t===b)));render()});document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=category===b.dataset.category?'':b.dataset.category;status='All';document.querySelectorAll('[data-status]').forEach(t=>t.setAttribute('aria-selected',String(t.dataset.status==='All')));render();$('#reports').scrollIntoView()});$('#search').oninput=e=>{query=e.target.value;render()};function showReports(){document.querySelectorAll('.mobile-nav button').forEach(b=>b.classList.toggle('selected',b.hasAttribute('data-reports')));$('#reports').scrollIntoView()}document.querySelectorAll('[data-reports]').forEach(b=>b.onclick=showReports);$('#viewAll').onclick=()=>{category='';query='';status='All';$('#search').value='';document.querySelectorAll('[data-status]').forEach(t=>t.setAttribute('aria-selected',String(t.dataset.status==='All')));render();showReports()};document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>{window.scrollTo({top:0,behavior:'smooth'});document.querySelectorAll('.mobile-nav button').forEach(t=>t.classList.toggle('selected',t.hasAttribute('data-home')))});
$('#location').onclick=()=>{openSheet(`<span class="category-icon blue"><i data-lucide="map-pin"></i></span><h2>Explore your city</h2><p>Choose a city to browse local reports. Location access will be requested when you report an issue.</p>${[['Raipur','Chhattisgarh'],['Bengaluru','Karnataka'],['New Delhi','Delhi'],['Mumbai','Maharashtra']].map(([name,state])=>`<button class="city-option" data-city="${name}" data-state="${state}"><span>${name}<small>${state}</small></span><i data-lucide="${city===name?'check':'chevron-right'}"></i></button>`).join('')}`);document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>{city=b.dataset.city;$('#cityName').textContent=`${city}, ${b.dataset.state}`;closeSheet();render()})};
$('#report').onclick=()=>{openSheet(`<span class="category-icon blue"><i data-lucide="camera"></i></span><h2>Every report starts<br>with what you see.</h2><p>You’ll need your location, a photo or video, and a nearby landmark. No account required.</p><div class="detail-label">HOME SCREEN PREVIEW</div><p>The reporting steps will be built next. For now, explore the issue categories and sample reports on the home screen.</p><button class="primary" id="back">Got it</button>`);$('#back').onclick=closeSheet};
function profile(){openSheet(`<span class="category-icon blue"><i data-lucide="user-round"></i></span><h2>You’re welcome here.<br>Account or no account.</h2><p>You can browse and report without signing up. An optional account will help you keep your reports together.</p><p>Sign-in will be added with the next flows.</p><button class="primary" id="browse">Explore reports</button>`);$('#browse').onclick=()=>{closeSheet();showReports()}}$('#profile').onclick=profile;document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=profile);$('#about').onclick=()=>openSheet(`<span class="category-icon blue"><i data-lucide="sprout"></i></span><h2>A simpler way to<br>care for your city.</h2><p>Civic is a design assignment concept for one national reporting service, with complaints routed to local departments.</p><p>This is an interactive home screen preview. All reports and department details are sample data. It is not an official Government of India service.</p>`);render();


